# Generated by palette from theme "{{ theme }}". Edits are overwritten on the next switch.
# Use from bordersrc:
#   source "$HOME/.config/palette/current/borders.sh"
#   borders active_color=$ACTIVE_COLOR inactive_color=$INACTIVE_COLOR

ACTIVE_COLOR={{ accent | argb }}
INACTIVE_COLOR={{ muted | argb }}

# Every theme colour, for Palette's Borders settings (Settings → Borders).
C_accent={{ accent | argb }}
C_selection={{ selection | argb }}
C_muted={{ muted | argb }}
C_background={{ background | argb }}
C_dark_background={{ dark_background | argb }}
C_darker_background={{ darker_background | argb }}
C_lighter_background={{ lighter_background | argb }}
C_foreground={{ foreground | argb }}
C_dark_foreground={{ dark_foreground | argb }}
C_light_foreground={{ light_foreground | argb }}
C_bright_foreground={{ bright_foreground | argb }}
C_red={{ red | argb }}
C_yellow={{ yellow | argb }}
C_green={{ green | argb }}
C_cyan={{ cyan | argb }}
C_blue={{ blue | argb }}
C_magenta={{ magenta | argb }}
C_orange={{ orange | argb }}
C_brown={{ brown | argb }}
C_bright_red={{ bright_red | argb }}
C_bright_yellow={{ bright_yellow | argb }}
C_bright_green={{ bright_green | argb }}
C_bright_cyan={{ bright_cyan | argb }}
C_bright_blue={{ bright_blue | argb }}
C_bright_magenta={{ bright_magenta | argb }}
